package Day3;

public class WhileLoopDemo2 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
        int i=1;
        while(i<=5)
        {
        	System.out.println("Dev Kumar Chaunbey "+i);
        	i=i+1;
        }
	}
	
	}


